/** Real client resource baking and native meshes, without Computer Use or changing a game world. */
@EventBusSubscriber(modid="thaumcraft_r3_test",value=Dist.CLIENT)
public final class ClientOuterRuntimeVerification {
    private static boolean done;
    @SubscribeEvent public static void tick(ClientTickEvent.Post event)throws Exception {
        if(done||!"outer-runtime-client".equals(System.getProperty("thaumcraft.r3.phase")))return;var mc=net.minecraft.client.Minecraft.getInstance();if(!(mc.screen instanceof net.minecraft.client.gui.screens.TitleScreen)||mc.getOverlay()!=null)return;done=true;
        var result=new com.google.gson.JsonObject();var checks=new ArrayList<String>();try {
            var inset=Class.forName("thaumcraft.client.RoomStoneModels").getDeclaredMethod("inset",net.minecraft.client.renderer.block.model.BakedQuad.class,int.class);inset.setAccessible(true);
            for(var block:List.of(thaumcraft.registry.R5Content.CARVED_STONE,thaumcraft.registry.R5Content.ANCIENT_RUNIC_STONE,thaumcraft.registry.R5Content.DECORATED_STONE)){var model=mc.getBlockRenderer().getBlockModel(block.get().defaultBlockState());var quads=model.getQuads(block.get().defaultBlockState(),null,net.minecraft.util.RandomSource.create(1));if(quads.size()!=6)throw new AssertionError("Room stone must bake six uncullable faces: "+block.getId());for(var quad:quads)for(int mask=0;mask<64;mask++){var cropped=(net.minecraft.client.renderer.block.model.BakedQuad)inset.invoke(null,quad,mask);if(cropped.isShade()||cropped.hasAmbientOcclusion())throw new AssertionError("Insets must retain original unshaded rendering");var source=quad.getVertices();var vertices=cropped.getVertices();int stride=net.neoforged.neoforge.client.model.IQuadTransformer.STRIDE,position=net.neoforged.neoforge.client.model.IQuadTransformer.POSITION,uv=net.neoforged.neoforge.client.model.IQuadTransformer.UV0;for(int vertex=0;vertex<4;vertex++)for(int axis=0;axis<3;axis++){int low=new int[]{4,0,2}[axis],high=low+1;float from=(mask&(1<<low))==0?0:.125f,to=(mask&(1<<high))==0?1:.875f,old=Float.intBitsToFloat(source[vertex*stride+position+axis]),actual=Float.intBitsToFloat(vertices[vertex*stride+position+axis]);if(Math.abs(actual-(old==0?from:to))>1e-6)throw new AssertionError("Baked bounds mismatch");}if(mask==63)for(int channel=0;channel<2;channel++){float oldMin=Float.POSITIVE_INFINITY,oldMax=Float.NEGATIVE_INFINITY,min=Float.POSITIVE_INFINITY,max=Float.NEGATIVE_INFINITY;for(int vertex=0;vertex<4;vertex++){float old=Float.intBitsToFloat(source[vertex*stride+uv+channel]),value=Float.intBitsToFloat(vertices[vertex*stride+uv+channel]);oldMin=Math.min(oldMin,old);oldMax=Math.max(oldMax,old);min=Math.min(min,value);max=Math.max(max,value);}if(Math.abs(min-(oldMin+(oldMax-oldMin)*.125f))>1e-6||Math.abs(max-(oldMax-(oldMax-oldMin)*.125f))>1e-6)throw new AssertionError("Original inset texture must be cropped, not stretched");}checks.add(block.getId()+" face "+quad.getDirection()+" mask "+mask);}}
            for(String kind:List.of("cultist_plate","cultist_robe","cultist_leader"))for(boolean inner:new boolean[]{false,true}){var model=thaumcraft.client.OriginalArmorGeometry.bake(kind,inner);if(model.head==null||model.body==null)throw new AssertionError("Armor failed native bake");var pieces=thaumcraft.client.OriginalArmorGeometry.class.getDeclaredField("pieces");pieces.setAccessible(true);int expected=7+(kind.equals("cultist_plate")?(inner?26:36):kind.equals("cultist_leader")?(inner?32:50):(inner?49:45));if(((Map<?,?>)pieces.get(model)).size()!=expected)throw new AssertionError("Original inner/outer armor attachment mismatch: "+kind+" inner="+inner);checks.add("Original armor native bake: "+kind+" inner="+inner);}
            var crab=Class.forName("thaumcraft.client.EldritchCrabModel").getDeclaredMethod("bake");crab.setAccessible(true);var root=(net.minecraft.client.model.geom.ModelPart)crab.invoke(null);if(root.getAllParts().count()!=22)throw new AssertionError("Crab native mesh requires root and all21parts");checks.add("All 21 original crab cuboids bake in real client");
            var mesh=Class.forName("thaumcraft.client.OriginalObjMesh").getDeclaredMethod("get",String.class);mesh.setAccessible(true);for(String id:List.of("vcrystal","crabvent")){if(mesh.invoke(null,id)==null)throw new AssertionError("OBJ absent: "+id);checks.add("Original OBJ parsed by runtime renderer: "+id);}
            for(String item:List.of("ancient_crystal","runic_key","eldritch_crab_spawner","carved_eldritch_stone","ancient_runic_stone","decorated_eldritch_stone","eldritch_door_stone")){var stack=new net.minecraft.world.item.ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("thaumcraft",item)));var model=mc.getItemRenderer().getModel(stack,null,null,0);if(model==mc.getModelManager().getMissingModel())throw new AssertionError("Missing baked item "+item);checks.add("Native item model resolves: "+item);}
            for(String sound:List.of("crystal","crabtalk","crabdeath","crabclaw","gore")){var eventSound=mc.getSoundManager().getSoundEvent(net.minecraft.resources.ResourceLocation.fromNamespaceAndPath("thaumcraft",sound));if(eventSound==null||eventSound.getWeight()<=0)throw new AssertionError("Original sound has no loaded recording: "+sound);checks.add("Native sound manager loads original recordings: "+sound);}
            result.addProperty("passed",true);result.addProperty("driver",org.lwjgl.opengl.GL11.glGetString(org.lwjgl.opengl.GL11.GL_RENDERER));
        }catch(Throwable error){result.addProperty("passed",false);result.addProperty("error",error.toString());}
        var payload=new com.google.gson.JsonObject();try(var artifact=new java.util.zip.ZipFile(java.nio.file.Path.of(System.getProperty("thaumcraft.r3.root"),"mod/build/libs/thaumcraft-1.21.1-0.2.0-r3-dev.jar").toFile())){var roots=List.of("thaumcraft/client/RoomStoneModels","thaumcraft/client/OuterRoomRenderers","thaumcraft/client/OriginalObjMesh","thaumcraft/client/OriginalArmorGeometry","thaumcraft/client/ArmorClientExtensions","thaumcraft/client/LegacyParticles","thaumcraft/client/EldritchCrabModel","thaumcraft/client/EldritchCrabRenderer","thaumcraft/client/AncientCrystalItemRenderer","thaumcraft/blocks/RoomStoneBounds","thaumcraft/blocks/AncientCrystal","thaumcraft/blocks/EldritchCrabSpawner","thaumcraft/blocks/EldritchTrap","thaumcraft/blocks/EldritchRoomStone","thaumcraft/entities/EldritchCrab","thaumcraft/entities/LegacyRiderPosition","thaumcraft/client/ThaumcraftRenderTypes","thaumcraft/entities/R5Entities","thaumcraft/registry/R5Content","thaumcraft/registry/R2Sounds","thaumcraft/items/CultistArmorItem","thaumcraft/world/dim/BossCycleData");for(var entry:Collections.list(artifact.entries())){String path=entry.getName();if(path.endsWith(".class")&&roots.stream().anyMatch(path::startsWith)){try(var stream=ClientOuterRuntimeVerification.class.getClassLoader().getResourceAsStream(path)){if(stream==null)throw new AssertionError("Runtime class absent "+path);payload.addProperty(path,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(stream.readAllBytes())));}}else if(path.startsWith("assets/thaumcraft/entity_models/eldritch_crab")||path.startsWith("assets/thaumcraft/armor_models/cultist_")||path.equals("assets/thaumcraft/sounds.json")||List.of("crab.png","craboverlay.png","crabvent.obj","crabvent.png","vcrystal.obj","vcrystal.png","cultist_leader_armor.png","cultist_plate_armor.png","cultist_robe_armor.png","cultistboots.png").stream().anyMatch(name->path.equals("assets/thaumcraft/textures/models/"+name))){try(var stream=mc.getResourceManager().getResourceOrThrow(net.minecraft.resources.ResourceLocation.parse("thaumcraft:"+path.substring("assets/thaumcraft/".length()))).open()){payload.addProperty(path,java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(stream.readAllBytes())));}}}}result.add("payload_sha256",payload);
        result.add("checks",new com.google.gson.Gson().toJsonTree(checks));result.addProperty("count",checks.size());result.addProperty("time",java.time.Instant.now().toString());result.addProperty("manual_acceptance","pending");java.nio.file.Files.writeString(java.nio.file.Path.of(System.getProperty("thaumcraft.r3.root"),"analysis/full_port/outer-runtime-client.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(result)+"\n");mc.stop();
    }
    private ClientOuterRuntimeVerification(){}
}
